const WORDS = {
  Animals: `Elephant, Penguin, Octopus, Giraffe, Dolphin, Hedgehog, Flamingo, Kangaroo, Chameleon, Peacock, Jellyfish, Raccoon, Tortoise, Squirrel, Cheetah, Koala, Crocodile, Platypus, Hummingbird, Porcupine, Walrus, Meerkat, Piranha, Llama, Seahorse, Badger, Parrot, Leopard, Mantis, Otter`,
  Food: `Pancake, Avocado, Sushi, Popcorn, Lasagna, Watermelon, Croissant, Dumpling, Cheesecake, Pineapple, Burrito, Pretzel, Blueberry, Tiramisu, Broccoli, Nachos, Coconut, Waffle, Meatball, Strawberry, Hummus, Cupcake, Spaghetti, Pickle, Donut, Mango, Omelette, Marshmallow, Taco, Cucumber`,
  Countries: `Japan, Brazil, Iceland, Morocco, Australia, Greece, Canada, Thailand, Kenya, Portugal, Mexico, Norway, India, Argentina, Egypt, Vietnam, Ireland, Peru, Finland, Jamaica, Turkey, Chile, New Zealand, Spain, South Korea, Madagascar, Switzerland, Colombia, Nepal, South Africa`,
  Cities: `Paris, Tokyo, New York, Barcelona, Cairo, Amsterdam, Rio de Janeiro, Seoul, London, Venice, Istanbul, Sydney, Kyoto, Marrakech, Singapore, Lisbon, Vancouver, Mumbai, Reykjavík, Florence, Mexico City, Bangkok, Cape Town, Chicago, Havana, Prague, Dubai, Athens, Nairobi, Buenos Aires`,
  Movies: `Jaws, Toy Story, The Matrix, Titanic, Jurassic Park, Finding Nemo, The Lion King, Home Alone, Inception, Frozen, Shrek, The Godfather, Coco, Avatar, The Wizard of Oz, Ghostbusters, Rocky, Ratatouille, E.T., Black Panther, Interstellar, The Incredibles, Mean Girls, Up, Gladiator, Barbie, Spider-Man, Casablanca, Moana, Paddington`,
  Sports: `Basketball, Tennis, Surfing, Fencing, Figure skating, Baseball, Rock climbing, Volleyball, Archery, Rugby, Snowboarding, Badminton, Boxing, Skateboarding, Golf, Rowing, Gymnastics, Table tennis, Marathon, Hockey, Diving, Cricket, Wrestling, Skiing, Cycling, Taekwondo, Soccer, Bowling, Canoeing, Pickleball`,
  Technology: `Smartphone, Drone, Robot, Headphones, 3D printer, Game controller, Satellite, Electric car, Laptop, Virtual reality, Smartwatch, Microchip, Camera, Keyboard, Telescope, Solar panel, Wi-Fi router, E-reader, Microphone, Projector, Selfie stick, Calculator, Flash drive, Touchscreen, Barcode scanner, Robot vacuum, Podcast, Video game, Bluetooth speaker, Space station`,
  Objects: `Umbrella, Key, Mirror, Suitcase, Candle, Backpack, Scissors, Toothbrush, Compass, Pillow, Sunglasses, Hourglass, Ladder, Teapot, Wallet, Skateboard, Magnet, Doormat, Thermos, Ruler, Binoculars, Stapler, Balloon, Hammock, Wrench, Snow globe, Feather duster, Alarm clock, Origami, Soap`,
  Professions: `Astronaut, Chef, Detective, Architect, Firefighter, Photographer, Beekeeper, Dentist, Pilot, Magician, Gardener, Sculptor, Teacher, Lifeguard, Meteorologist, Baker, Veterinarian, Cartographer, Zookeeper, Drummer, Journalist, Tailor, Paramedic, Archaeologist, Florist, Sailor, Animator, Judge, Locksmith, Park ranger`,
  Celebrities: `Taylor Swift, Beyoncé, Keanu Reeves, Zendaya, Dwayne Johnson, Billie Eilish, Tom Hanks, Rihanna, Pedro Pascal, Dolly Parton, Emma Stone, Bad Bunny, Oprah Winfrey, Ryan Reynolds, Serena Williams, Snoop Dogg, Lady Gaga, Jackie Chan, Adele, LeBron James, Emma Watson, Bruno Mars, Gordon Ramsay, Shakira, Chris Hemsworth, Dua Lipa, Morgan Freeman, Lionel Messi, Miley Cyrus, Harry Styles`,
  Nature: `Waterfall, Volcano, Rainbow, Glacier, Coral reef, Thunderstorm, Desert, Redwood, Aurora, Moonlight, Wildflower, Canyon, Tidal wave, Fossil, Sand dune, Mushroom, Snowflake, Hot spring, Eclipse, Bamboo forest, Seashell, Lightning, Mountain peak, Pinecone, River delta, Moss, Comet, Tide pool, Redwood forest, Firefly`,
  Transportation: `Hot air balloon, Subway, Sailboat, Tractor, Helicopter, Tandem bicycle, Cable car, Canoe, Motorcycle, Spaceship, Tram, Skateboard, Rickshaw, Ferry, Snowmobile, Monorail, Train, Segway, Gondola, Double-decker bus, Glider, Jet ski, Delivery van, Horse-drawn carriage, Rocket, Scooter, Cargo ship, Unicycle, Taxi, Airplane`,
  'Random Mix': `Karaoke, Birthday cake, Treasure map, Pillow fort, Snowman, Roller coaster, Secret agent, Time machine, Campfire, Magic trick, School dance, Haunted house, Treasure chest, Costume party, Soap bubbles, Photo booth, Paper airplane, Secret handshake, Sleepover, Board game, Sandcastle, Fortune cookie, Puppet show, Fireworks, Diary, Water balloon, Pirate ship, Treehouse, Traffic jam, Magic carpet`
};
const BASE_CATEGORIES = Object.keys(WORDS);
const DEFAULT_NAMES = ['Alex','Sam','Jordan','Taylor'];
const state = {
  players: JSON.parse(localStorage.getItem('imposter.players') || 'null') || [...DEFAULT_NAMES],
  scores: JSON.parse(localStorage.getItem('imposter.scores') || '{}'),
  settings: JSON.parse(localStorage.getItem('imposter.settings') || 'null') || { imposters: 1, timer: 60, guess: true, categories: ['Random Mix'] },
  customPacks: JSON.parse(localStorage.getItem('imposter.packs') || '[]'),
  usedWords: [], round: 1, phase: 'setup', roleIndex: 0, clueIndex: 0, voteIndex: 0,
  roles: [], word: '', clues: [], votes: {}, selectedVote: null, seconds: 0, interval: null,
  result: null, sound: true, revealed: false, editing: -1
};
const app = document.querySelector('#app');
const toastEl = document.querySelector('#toast');
function save(){ localStorage.setItem('imposter.players',JSON.stringify(state.players));localStorage.setItem('imposter.scores',JSON.stringify(state.scores));localStorage.setItem('imposter.settings',JSON.stringify(state.settings));localStorage.setItem('imposter.packs',JSON.stringify(state.customPacks)); }
function esc(s){ return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.classList.remove('show'),2100)}
function randomize(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function allCategories(){return [...BASE_CATEGORIES,...state.customPacks.map(p=>p.name)]}
function wordsFor(category){const custom=state.customPacks.find(p=>p.name===category);return custom?custom.words:WORDS[category]||[]}
function render(){clearInterval(state.interval);if(state.phase==='setup')renderSetup();else if(state.phase==='deal')renderDeal();else if(state.phase==='clues')renderClues();else if(state.phase==='discussion')renderDiscussion();else if(state.phase==='vote')renderVote();else if(state.phase==='result')renderResult()}
function renderSetup(){
 const categories=allCategories();if(!state.settings.categories.length)state.settings.categories=['Random Mix'];
 app.innerHTML=`<section class="hero-line"><div><div class="eyebrow">A party game for 3–12 players</div><h1>One word.<br><em>One liar.</em></h1></div><p class="hero-copy">Everyone knows the word. Except the one person pretending they do.</p></section>
 <div class="setup-grid"><section class="panel players-panel"><div class="panel-heading"><h2>Who's playing?</h2><span class="count-pill"><strong>${state.players.length}</strong> / 12 PLAYERS</span></div>
 <form id="addForm" class="add-player"><input id="playerInput" class="text-input" maxlength="20" autocomplete="off" placeholder="Type a name and hit enter" aria-label="Player name"><button class="add-btn" type="submit">+ Add player</button></form>
 <div class="player-list">${state.players.length?state.players.map((name,i)=>`<div class="player-row"><span class="avatar">${esc(name.trim().charAt(0).toUpperCase()||'?')}</span>${state.editing===i?`<input class="edit-name" data-index="${i}" maxlength="20" value="${esc(name)}" aria-label="Edit player name">`:`<span class="player-name">${esc(name)}</span>`}<button class="row-action edit-action" data-index="${i}" title="Edit name" aria-label="Edit ${esc(name)}">✎</button><button class="row-action remove-action" data-index="${i}" title="Remove player" aria-label="Remove ${esc(name)}">×</button></div>`).join(''):'<div class="empty-note">Add at least 3 players to get the game going.</div>'}</div>
 <div class="player-footer"><span class="helper">${state.players.length<3?'You need at least 3 players.':state.players.length===12?'That’s a full room!':'Add up to 12 players.'}</span><button class="text-btn" id="shufflePlayers">↻ &nbsp;Randomize order</button></div></section>
 <aside class="panel settings-panel"><h2 class="settings-title">Make it your game</h2>
 <div class="setting-group"><div class="setting-label"><span>Number of imposters</span><span class="setting-value">${state.settings.imposters} SELECTED</span></div><div class="segmented" id="imposterChoices">${[1,2,3].map(n=>`<button data-value="${n}" class="${state.settings.imposters===n?'active':''}">${n} ${n===1?'imposter':'imposters'}</button>`).join('')}</div></div>
 <div class="setting-group"><div class="toggle-line"><span>Final word guess</span><input id="guessToggle" class="switch" type="checkbox" ${state.settings.guess?'checked':''} aria-label="Enable imposter final guess"></div><div class="helper" style="margin-top:7px">Caught? Guess the word to steal the win.</div></div>
 <div class="setting-group"><div class="toggle-line"><span>Discussion timer</span><input id="timerToggle" class="switch" type="checkbox" ${state.settings.timer?'checked':''} aria-label="Enable discussion timer"></div><div id="timerOptions" style="margin-top:11px;${state.settings.timer?'':'display:none'}"><div class="segmented">${[30,60,90,120].map(n=>`<button data-timer="${n}" class="${state.settings.timer===n?'active':''}">${n}s</button>`).join('')}</div></div></div>
 <div class="setting-group"><div class="category-head"><div class="setting-label"><span>Word categories</span></div><button class="mini-link" id="toggleAll">${categories.every(c=>state.settings.categories.includes(c))?'CLEAR':'SELECT ALL'}</button></div><div class="category-grid">${categories.map(c=>`<button class="category-chip ${state.settings.categories.includes(c)?'selected':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><button class="custom-pack-link" id="openPack">＋ &nbsp;Create a custom word pack</button></div>
 <div class="start-wrap"><button id="startGame" class="primary-btn">START GAME &nbsp;→</button><div class="validation" id="validation">${state.players.length<3?'Add '+(3-state.players.length)+' more player'+(3-state.players.length===2?'s':'')+' to start.':state.settings.imposters>=state.players.length?'Keep at least two players out of the imposter team.':''}</div></div>
 <div class="setup-footnote">PASS THE PHONE · NO PEEKING · NO TAKING IT PERSONALLY</div></aside></div>`;
 document.querySelector('#addForm').addEventListener('submit',e=>{e.preventDefault();addPlayer()});
 document.querySelectorAll('.remove-action').forEach(b=>b.onclick=()=>{state.players.splice(+b.dataset.index,1);state.editing=-1;save();render()});
 document.querySelectorAll('.edit-action').forEach(b=>b.onclick=()=>{state.editing=+b.dataset.index;render();const i=document.querySelector('.edit-name');i?.focus();i?.select()});
 const editInput=document.querySelector('.edit-name');if(editInput){editInput.onkeydown=e=>{if(e.key==='Enter'||e.key==='Escape')saveEdit(e.key==='Enter')};editInput.onblur=()=>saveEdit(true)}
 document.querySelector('#shufflePlayers').onclick=()=>{randomize(state.players);save();render();toast('Player order shuffled')};
 document.querySelector('#imposterChoices').onclick=e=>{const b=e.target.closest('[data-value]');if(!b)return;state.settings.imposters=+b.dataset.value;save();render()};
 document.querySelector('#guessToggle').onchange=e=>{state.settings.guess=e.target.checked;save()};
 document.querySelector('#timerToggle').onchange=e=>{state.settings.timer=e.target.checked?(state.settings.timer||60):0;save();render()};
 document.querySelectorAll('[data-timer]').forEach(b=>b.onclick=()=>{state.settings.timer=+b.dataset.timer;save();render()});
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{const c=b.dataset.category;state.settings.categories=state.settings.categories.includes(c)?state.settings.categories.filter(x=>x!==c):[...state.settings.categories,c];save();render()});
 document.querySelector('#toggleAll').onclick=()=>{state.settings.categories=categories.every(c=>state.settings.categories.includes(c))?[]:[...categories];save();render()};
 document.querySelector('#openPack').onclick=openPackModal;
 document.querySelector('#startGame').onclick=startGame;
}
function addPlayer(){const input=document.querySelector('#playerInput'),name=input.value.trim();if(!name)return;if(state.players.length>=12){toast('The room is full (12 players max).');return}if(state.players.some(n=>n.toLowerCase()===name.toLowerCase())){toast('That name is already in the room.');input.focus();return}state.players.push(name);save();render();document.querySelector('#playerInput').focus()}
function saveEdit(commit){const input=document.querySelector('.edit-name');if(!input)return;const idx=+input.dataset.index;const name=input.value.trim();if(commit&&name&&!state.players.some((n,i)=>i!==idx&&n.toLowerCase()===name.toLowerCase()))state.players[idx]=name;else if(commit&&name)toast('Choose a name that’s not already taken.');state.editing=-1;save();render()}
function openPackModal(){app.insertAdjacentHTML('beforeend',`<div class="pack-modal" id="packModal"><div class="modal-card"><h2>Make your own word pack</h2><p>Give it a name and add words separated by commas or new lines. Packs are saved on this device.</p><label for="packName">Pack name</label><input id="packName" class="text-input" maxlength="24" placeholder="Inside jokes, anyone?"><label for="packWords">Your words (at least 5)</label><textarea id="packWords" placeholder="The cabin&#10;Milo's terrible cooking&#10;That one summer"></textarea><div class="modal-actions"><button class="secondary-btn" id="cancelPack">Cancel</button><button class="primary-btn" id="savePack">Save word pack</button></div></div></div>`);
 document.querySelector('#cancelPack').onclick=()=>document.querySelector('#packModal').remove();document.querySelector('#packModal').onclick=e=>{if(e.target.id==='packModal')e.currentTarget.remove()};document.querySelector('#savePack').onclick=()=>{const name=document.querySelector('#packName').value.trim(),words=[...new Set(document.querySelector('#packWords').value.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean))];if(!name||words.length<5){toast('Add a name and at least 5 unique words.');return}if(allCategories().some(c=>c.toLowerCase()===name.toLowerCase())){toast('That category name is already in use.');return}state.customPacks.push({name,words});state.settings.categories.push(name);save();render();toast('Word pack saved!')}};
function startGame(){const v=document.querySelector('#validation');if(state.players.length<3||state.settings.imposters>=state.players.length||state.settings.imposters<1){if(v)v.textContent=state.players.length<3?'Add at least 3 players to start.':'Leave at least two non-imposters in the game.';return}if(!state.settings.categories.length){if(v)v.textContent='Pick at least one word category.';return}
 const pool=[...new Set(state.settings.categories.flatMap(wordsFor))];if(!pool.length){toast('That word pack is empty. Choose another category.');return}let fresh=pool.filter(w=>!state.usedWords.includes(w));if(!fresh.length){state.usedWords=[];fresh=pool}state.word=fresh[Math.floor(Math.random()*fresh.length)];state.usedWords.push(state.word);const order=randomize([...state.players]);const bad=randomize([...order]).slice(0,state.settings.imposters);state.roles=order.map(name=>({name,imposter:bad.includes(name)}));state.clues=[];state.votes={};state.voteIndex=0;state.roleIndex=0;state.revealed=false;state.phase='deal';render()}

input.newString:
state.phase='deal';render()}
function renderDeal(){const p=state.roles[state.roleIndex];const last=state.roleIndex===state.roles.length-1;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> SECRET ROLE</div><span class="round-tag">${state.roleIndex+1} OF ${state.players.length}</span></div><section class="panel phase-card"><div class="step-count">PRIVATE SCREEN · ONLY ${esc(p.name.toUpperCase())} SHOULD LOOK</div><h1>Pass the phone<br>to <em>${esc(p.name)}.</em></h1><p class="phase-description">Make sure everyone else is looking away. Tap below when you’re ready to see your role.</p><div class="secret-box ${state.revealed?'':'hidden'}">${state.revealed?`<div class="secret-value">${p.imposter?'IMPOSTER':esc(state.word.toUpperCase())}</div><div class="secret-role ${p.imposter?'danger':''}">${p.imposter?'BLEND IN. YOU DO NOT KNOW THE WORD.':'YOU ARE IN THE KNOW · KEEP IT SECRET'}</div>`:`<div class="secret-value" style="color:#a7aaa0">••••••••</div><div class="secret-role">YOUR ROLE IS HIDDEN</div>`}</div><p class="hold-note">${state.revealed?'Memorize it. Then tap hide before passing the phone.':'No peeking, everyone else 👀'}</p><div class="action-row">${state.revealed?`<button id="hideRole" class="secondary-btn">Hide my role</button><button id="nextRole" class="primary-btn">${last?'EVERYONE’S READY':'PASS TO NEXT PLAYER'} &nbsp;→</button>`:`<button id="revealRole" class="primary-btn">REVEAL MY ROLE &nbsp;👁</button>`}</div><div class="progress-dots">${state.roles.map((_,i)=>`<span class="${i<=state.roleIndex?'done':''}"></span>`).join('')}</div></section><div class="setup-footnote">KEEP YOUR SCREEN TO YOURSELF — THE WHOLE GAME DEPENDS ON IT</div></div>`;
 document.querySelector('#revealRole').onclick=()=>{state.revealed=true;render()};if(state.revealed){document.querySelector('#hideRole').onclick=()=>{state.revealed=false;render()};document.querySelector('#nextRole').onclick=()=>{state.revealed=false;if(last){state.phase='clues';state.clueIndex=0}else state.roleIndex++;render()}}
}
function renderClues(){const p=state.roles[state.clueIndex];const done=state.clueIndex>=state.roles.length;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> CLUE ROUND</div><span class="round-tag">${Math.min(state.clueIndex+1,state.players.length)} OF ${state.players.length}</span></div><section class="panel clue-card"><div class="clue-top"><h2 class="settings-title">One clue. Keep it clever.</h2><span class="pill-info">NO SAYING THE WORD</span></div>${done?`<div class="center"><p class="phase-description">All clues are in. Talk it out, then cast your votes.</p><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div><button id="beginDiscussion" class="primary-btn" style="max-width:320px">${state.settings.timer?'START DISCUSSION TIMER':'GO TO VOTING'} &nbsp;→</button></div>`:`<div class="current-turn"><span class="avatar">${esc(p.name.charAt(0).toUpperCase())}</span><div><strong>${esc(p.name)}’s turn</strong><small>Pass the phone privately</small></div></div><div class="clue-entry"><input id="clueInput" class="text-input" maxlength="35" autocomplete="off" placeholder="Type a one-word clue…"><button id="submitClue" class="add-btn">Give clue →</button></div><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div>`}</section><div class="setup-footnote">HINTS, NOT DEFINITIONS. GIVE THEM SOMETHING TO DISCUSS.</div></div>`;
 if(done){document.querySelector('#beginDiscussion').onclick=()=>{if(state.settings.timer){state.phase='discussion';state.seconds=state.settings.timer;render();startTimer()}else{state.phase='vote';render()}}}else{const input=document.querySelector('#clueInput');document.querySelector('#submitClue').onclick=submitClue;input.onkeydown=e=>{if(e.key==='Enter')submitClue()};input.focus()}}
function submitClue(){const input=document.querySelector('#clueInput'),clue=input.value.trim();if(!clue){toast('Add a clue before passing the phone.');return}if(clue.toLowerCase()===state.word.toLowerCase()){toast('Oops — don’t give the word away!');return}state.clues.push({name:state.roles[state.clueIndex].name,clue});state.clueIndex++;render()}
function startTimer(){clearInterval(state.interval);state.interval=setInterval(()=>{state.seconds--;if(state.seconds<=0){clearInterval(state.interval);state.seconds=0;state.phase='vote';render();toast('Time’s up! Time to vote.');return}const el=document.querySelector('#timerValue');if(el){el.textContent=clock(state.seconds);if(state.seconds<=10)el.classList.add('urgent')}},1000)}
function clock(s){return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
function renderDiscussion(){app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> DISCUSSION</div><span class="round-tag">GET TALKING</span></div><section class="panel phase-card discussion-card"><div class="eyebrow">TIME LEFT</div><div class="timer" id="timerValue">${clock(state.seconds)}</div><p class="phase-description">Compare the clues. Who sounds like they’re bluffing? Make your case, but don’t give the word away.</p><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div><div class="action-row"><button id="endDiscussion" class="primary-btn" style="max-width:300px">WE’RE READY TO VOTE &nbsp;→</button></div></section><div class="setup-footnote">EVERYONE HAS ONE VOTE. YOU CAN’T VOTE FOR YOURSELF.</div></div>`;document.querySelector('#endDiscussion').onclick=()=>{clearInterval(state.interval);state.phase='vote';render()}}
function renderVote(){const voter=state.roles[state.voteIndex];const final=state.voteIndex===state.roles.length-1;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> PRIVATE VOTE</div><span class="round-tag">VOTE ${state.voteIndex+1} OF ${state.roles.length}</span></div><section class="panel phase-card"><div class="step-count">SECRET BALLOT · ONLY ${esc(voter.name.toUpperCase())} SHOULD LOOK</div><h1>${esc(voter.name)},<br>who’s the imposter?</h1><p class="phase-description">Choose one person you think is bluffing. No voting for yourself.</p><div class="vote-select">${state.roles.map((p,i)=>`<button class="vote-option ${state.selectedVote===i?'selected':''}" data-vote="${i}" ${p.name===voter.name?'disabled':''}><span class="avatar">${esc(p.name.charAt(0).toUpperCase())}</span><strong>${esc(p.name)}</strong></button>`).join('')}</div><div class="action-row"><button id="castVote" class="primary-btn" style="max-width:320px" ${state.selectedVote===null?'disabled':''}>${final?'LOCK IN & REVEAL VOTES':'SUBMIT SECRET VOTE'} &nbsp;→</button></div></section><div class="setup-footnote">YOUR VOTE IS PRIVATE UNTIL EVERYONE HAS VOTED.</div></div>`;
 document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{state.selectedVote=+b.dataset.vote;render()});document.querySelector('#castVote').onclick=()=>{if(state.selectedVote===null)return;state.votes[voter.name]=state.roles[state.selectedVote].name;state.selectedVote=null;if(final)resolveVotes();else state.voteIndex++;render()}}
function resolveVotes(){const counts=Object.fromEntries(state.players.map(n=>[n,0]));Object.values(state.votes).forEach(n=>counts[n]++);const max=Math.max(...Object.values(counts));const leaders=state.players.filter(n=>counts[n]===max);const imposters=state.roles.filter(p=>p.imposter).map(p=>p.name);const caught=imposters.filter(n=>leaders.includes(n));const win= caught.length===imposters.length;state.result={counts,max,leaders,imposters,caught,win,reason:win?'caught':'escaped'};if(win&&state.settings.guess){state.phase='guess';renderGuess()}else finishGame(win?'players':'imposters')}
function renderGuess(){const imposters=state.result.caught;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ONE LAST CHANCE</div><span class="round-tag">IMPOSTER GUESS</span></div><section class="panel phase-card"><div class="step-count">${imposters.map(n=>esc(n.toUpperCase())).join(' & ')}</div><h1>You’ve been found.<br><em>But do you know?</em></h1><p class="phase-description">The room got you. Guess the secret word correctly and steal the win for the imposter team.</p><form id="guessForm" class="clue-entry" style="max-width:400px;margin:0 auto"><input id="guessInput" class="text-input" maxlength="50" autocomplete="off" placeholder="Your final guess…"><button class="add-btn" type="submit">GUESS</button></form></section><div class="setup-footnote">ONE GUESS FOR THE IMPOSTER TEAM. TALK IT OVER.</div></div>`;document.querySelector('#guessForm').onsubmit=e=>{e.preventDefault();const guess=document.querySelector('#guessInput').value.trim();if(!guess){toast('Enter your guess first.');return}finishGame(guess.toLowerCase()===state.word.toLowerCase()?'imposters':'players',guess)}}

