const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1280,height:900}});
 const errors=[];page.on('pageerror',e=>errors.push(String(e)));
 await page.goto('http://localhost:3002');
 await page.evaluate(()=>localStorage.clear()); await page.reload();
 console.log('setup', await page.locator('#app').innerText().then(s=>s.slice(0,200)),'height',await page.locator('body').evaluate(e=>e.scrollHeight));
 await page.locator('#startGame').click();
 for(let i=0;i<4;i++){
   await page.locator('#revealRole').click();
   await page.locator('#hideRole').click();
   await page.locator('#nextRole').click();
 }
 console.log('after deal', (await page.locator('#app').innerText()).slice(0,180));
 for(let i=0;i<4;i++){
   await page.locator('#clueInput').fill('mystery');
   await page.locator('#submitClue').click();
 }
 await page.locator('#beginDiscussion').click();
 await page.locator('#endDiscussion').click();
 const roles=await page.evaluate(()=>state.roles.map(x=>({...x})));
 const imp=roles.find(x=>x.imposter).name;
 for(let i=0;i<roles.length;i++){
   const voter=roles[i].name;
   const target=voter===imp?roles.find(x=>x.name!==imp).name:imp;
   const button=page.locator('.vote-option').filter({hasText:target});
   await button.click(); await page.locator('#castVote').click();
 }
 console.log('guess stage', (await page.locator('#app').innerText()).slice(0,200));
 const word=await page.evaluate(()=>state.word);
 await page.locator('#guessInput').fill(word);
 await page.locator('#guessForm button[type=submit]').click();
 console.log('result', (await page.locator('#app').innerText()).slice(-500));
 await page.locator('#nextRound').click();
 console.log('next', await page.locator('#startGame').count(), 'scores',await page.evaluate(()=>localStorage.getItem('imposter.scores')),'errors',errors);
 await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/setup.jpg',type:'jpeg',quality:80,fullPage:true});
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

